package glitch

import data.glitch_lib

sensitive_names = {
    "password", "secret", "key", "token", "credential", "auth", "passphrase", 
    "secret_key", "api_key", "access_key", "secret_value", "encrypted_password",
    "ssh_key", "private_key", "admin_password", "db_user", "db_pass", 
    "api_token", "bearer_token", "access_token", "refresh_token", "github_token",
    "client_secret", "cert", "pem", "key_material", "ssh_public_key"
}

default_credentials = {
    "admin", "root", "default", "demo", "test", "guest", "password", "changeme"
}

suspicious_filenames = {
    "credentials", "secret", "key", "token", "id_rsa", "id_dsa", "known_hosts"
}

base64_functions = {"base64", "b64encode", "base64decode"}

api_token_prefixes = {"ghp_", "AKIA", "ASIA", "gho_", "ghu_", "github_", "Bearer ", "ghr_"}

credential_names = {
    "username", "user", "admin", "admin_user", "password", "pass", "admin_password", "db_user", "db_pass"
}

embedded_key_names = {"private_key", "cert", "pem", "key_material", "ssh_public_key", "client_secret"}

is_embedded_key(s) {
    contains(s, "\n")
} else {
    contains(s, "-----BEGIN")
} else {
    regex.match("^[A-Za-z0-9+/=]+$", s) and count(s) > 100
}

is_api_token(s) {
    count(s) >= 20
    some prefix in api_token_prefixes
    startswith(s, prefix)
} else {
    count(s) >= 30
    regex.match("^[A-Za-z0-9_-]+$", s)
}

is_sensitive_string(s) {
    lower_s := lower(s)
    some keyword in sensitive_names
    contains(lower_s, keyword)
} else {
    lower_s := lower(s)
    lower_s in default_credentials
}

is_suspicious_file_path(s) {
    lower_s := lower(s)
    some keyword in suspicious_filenames
    contains(lower_s, keyword)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    lower_name := lower(attr.name)
    some keyword in sensitive_names
    contains(lower_name, keyword)
    attr.value.ir_type == "String"
    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": sprintf("Hard-coded credential found in attribute '%s'. (CWE-798)", [attr.name])
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    lower_name := lower(var.name)
    some keyword in sensitive_names
    contains(lower_name, keyword)
    var.value.ir_type == "String"
    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": sprintf("Hard-coded credential found in variable '%s'. (CWE-798)", [var.name])
    }
}

